import{_ as l,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Jewel -- Calamari/API/Storage/Hardware","description":"","frontmatter":{"title":"CDS Jewel -- Calamari/API/Storage/Hardware","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","Calamari","API","硬件存储","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.md","filePath":"posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.md","lastUpdated":1780459816000}'),e={name:"posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.md"};function o(s,a,n,m,p,_){return i(),r("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="一、硬件api规划与实现" tabindex="-1">一、硬件API规划与实现 <a class="header-anchor" href="#一、硬件api规划与实现" aria-label="Permalink to &quot;一、硬件API规划与实现&quot;">​</a></h4><p><strong>会议主题</strong>： 讨论并规划Calamari硬件API的规划和实现。</p><p><strong>主要议题</strong>：</p><ul><li>通过提供硬件API，使Calamari能够了解其背后的存储，以便在硬件出现问题时，能够分析影响并帮助管理员识别合适的硬件进行更换。</li><li>API设计，包括设备ID、驱动器信息、制造商、版本、序列号等。</li><li>使用全球ID作为持久标识符，并确保其在不同场景下的一致性。</li><li>处理智能数据（Smart Data），包括存储位置、频率和缓存策略。</li><li>与现有工具（如libblockid）集成。</li></ul><p><strong>决定事项</strong>：</p><ul><li>将智能数据存储在Calamari中，并定期查询设备以获取数据。</li><li>使用libblockid等现有工具进行智能数据查询。</li><li>考虑使用缓存机制以避免频繁查询设备。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完成API的设计和实现。</li><li>在Calamari中集成智能数据。</li><li>测试API的功能。</li></ul><h4 id="二、calamari包发布" tabindex="-1">二、Calamari包发布 <a class="header-anchor" href="#二、calamari包发布" aria-label="Permalink to &quot;二、Calamari包发布&quot;">​</a></h4><p><strong>会议主题</strong>： 讨论Calamari包的发布和计划。</p><p><strong>主要议题</strong>：</p><ul><li>Calamari的最新稳定版本已发布，并可在download.com/calamari下载。</li><li>提供Calamari的安装指南，并链接到aether pad和GitHub的readme文件。</li><li>目前支持SUSE、Ubuntu和CentOS。</li><li>探索其他发行版的支持。</li></ul><p><strong>决定事项</strong>：</p><ul><li>发布Calamari包。</li><li>提供安装指南。</li><li>探索其他发行版的支持。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>发布Fedora 21+的包。</li><li>探索其他发行版的支持。</li></ul><h4 id="三、calamari故障排除" tabindex="-1">三、Calamari故障排除 <a class="header-anchor" href="#三、calamari故障排除" aria-label="Permalink to &quot;三、Calamari故障排除&quot;">​</a></h4><p><strong>会议主题</strong>： 讨论如何改进Calamari的故障排除。</p><p><strong>主要议题</strong>：</p><ul><li>Calamari使用salt进行自动化，但salt的最新版本可能会与Calamari冲突。</li><li>需要改进故障排除文档，使其更易于使用。</li><li>简化Calamari的依赖关系，使其更易于安装和使用。</li></ul><p><strong>决定事项</strong>：</p><ul><li>改进故障排除文档。</li><li>简化Calamari的依赖关系。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>改进故障排除文档。</li><li>简化Calamari的依赖关系。</li></ul><h4 id="四、其他讨论" tabindex="-1">四、其他讨论 <a class="header-anchor" href="#四、其他讨论" aria-label="Permalink to &quot;四、其他讨论&quot;">​</a></h4><ul><li>讨论了Calamari测试框架的设置和运行。</li><li>讨论了Calamari的未来发展方向，包括集成其他工具和功能。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Calamari硬件API的规划和实现、Calamari包的发布、Calamari的故障排除以及Calamari的未来发展方向。会议确定了后续行动计划，并讨论了相关技术问题。</p>',29)])])}const u=l(e,[["render",o]]);export{C as __pageData,u as default};
